macro_rules! WorkProduct {
    () => {
        # [doc = " A \"work product\" is an intermediate result that we save into the"] # [doc = " incremental directory for later re-use. The primary example are"] # [doc = " the object files that we save for each partition at code"] # [doc = " generation time."] # [doc = ""] # [doc = " Each work product is associated with a dep-node, representing the"] # [doc = " process that produced the work-product. If that dep-node is found"] # [doc = " to be dirty when we load up, then we will delete the work-product"] # [doc = " at load time. If the work-product is found to be clean, then we"] # [doc = " will keep a record in the `previous_work_products` list."] # [doc = ""] # [doc = " In addition, work products have an associated hash. This hash is"] # [doc = " an extra hash that can be used to decide if the work-product from"] # [doc = " a previous compilation can be re-used (in addition to the dirty"] # [doc = " edges check)."] # [doc = ""] # [doc = " As the primary example, consider the object files we generate for"] # [doc = " each partition. In the first run, we create partitions based on"] # [doc = " the symbols that need to be compiled. For each partition P, we"] # [doc = " hash the symbols in P and create a `WorkProduct` record associated"] # [doc = " with `DepNode::CodegenUnit(P)`; the hash is the set of symbols"] # [doc = " in P."] # [doc = ""] # [doc = " The next time we compile, if the `DepNode::CodegenUnit(P)` is"] # [doc = " judged to be clean (which means none of the things we read to"] # [doc = " generate the partition were found to be dirty), it will be loaded"] # [doc = " into previous work products. We will then regenerate the set of"] # [doc = " symbols in the partition P and hash them (note that new symbols"] # [doc = " may be added -- for example, new monomorphizations -- even if"] # [doc = " nothing in P changed!). We will compare that hash against the"] # [doc = " previous hash. If it matches up, we can reuse the object file."] # [derive (Clone , Debug , Encodable , Decodable)] pub struct WorkProduct { pub cgu_name : String , # [doc = " Saved files associated with this CGU. In each key/value pair, the value is the path to the"] # [doc = " saved file and the key is some identifier for the type of file being saved."] # [doc = ""] # [doc = " By convention, file extensions are currently used as identifiers, i.e. the key \"o\" maps to"] # [doc = " the object file's path, and \"dwo\" to the dwarf object file's path."] pub saved_files : UnordMap < String , String > , }
    };
}

WorkProduct!();